) v (job_id, skill, required, min_years, weight, evidence)
join public.skills s on s.name = v.skill;

-- Job vectors: centroid of the requirement skills, like save_requirements() -----------------------
update public.jobs j set embedding = public.skills_centroid(array(
    select jr.skill_id from public.job_requirements jr where jr.job_id = j.id)),
  embedding_model = 'gemini-embedding-001@1536'
where j.id::text like '484f5553-0001-%';

-- Roll everything back if any job came out incomplete.
do $$
declare bad text;
begin
  select string_agg(j.title, ', ') into bad
  from public.jobs j
  where j.id::text like '484f5553-0001-%'
    and (j.embedding is null or (select count(*) from public.job_requirements jr where jr.job_id = j.id) not between 3 and 10);
  if bad is not null then raise exception 'houston_jobs.sql: incomplete jobs: %', bad; end if;
  if (select count(*) from public.jobs where id::text like '484f5553-0001-%') <> 80 then
    raise exception 'houston_jobs.sql: expected 80 jobs';
  end if;
end $$;

commit;

-- Summary (expect 18 companies, 80 open jobs, 503 requirements, 80 vectors).
select
  (select count(*) from public.companies where id::text like '484f5553-0000-%') as companies,
  (select count(*) from public.jobs where id::text like '484f5553-0001-%' and status = 'OPEN' and expires_at > now()) as open_jobs,
  (select count(*) from public.job_requirements where job_id::text like '484f5553-0001-%') as requirements,
  (select count(*) from public.jobs where id::text like '484f5553-0001-%' and embedding is not null) as vectors;
